        groupSel[g.label] = new Set([optKey(o)]);
      } else {
        groupSel[g.label].delete(optKey(g.options[FIRST]));
        if (groupSel[g.label].has(optKey(o))) groupSel[g.label].delete(optKey(o));
        else groupSel[g.label].add(optKey(o));
        if (groupSel[g.label].size === 0) groupSel[g.label].add(optKey(g.options[FIRST]));
      }
      syncGroup(g);
      updateGroupCount(g);
      updateReqUrl();
    };
    chips.appendChild(c);
  });
  groupChips[g.label] = [...chips.children];
  card.appendChild(chips);
  groupsEl.appendChild(card);
  updateGroupCount(g);
}

function syncGroup(g){
  if (g.single){
    const sel = topSelects[g.label];
    if (sel) sel.value = [...groupSel[g.label]][0];
  }
  (groupChips[g.label] || []).forEach((x, idx) => {
    const o2 = g.options[idx];
    x.classList.toggle('on', groupSel[g.label].has(optKey(o2)));
  });
