function updateGroupCount(g){
  const el = document.getElementById('cnt_' + g.label);
  if (!el) return;
  if (g.single){ el.textContent = ''; return; }
  const n = groupSel[g.label].size - (groupSel[g.label].has(optKey(g.options[FIRST])) ? 1 : 0);
  el.textContent = n > 0 ? `已选 ${n}` : '';
}
