// ---------- 构建最终请求 URL（对齐晋江 android 接口） ----------
function buildSearchUrl(offset){
  const vars = {};
  const add = (key, val) => { const k = key.replace(/\d+/g, ''); (vars[k] = vars[k] || []).push(val); };
  DATA.groups.forEach(g => g.options.forEach(o => { if (groupSel[g.label].has(optKey(o))) add(o.name, o.value); }));
  const inc = [], exc = [];
  DATA.tags.forEach(t => { if (tagState[t.id] === 1) inc.push(t.id); if (tagState[t.id] === 2) exc.push(t.id); });
  inc.forEach(id => add('bq', id));
  exc.forEach(id => add('removebq', id));
  add('collectiontypes', incMethod);
  add('notlikecollectiontypes', excMethod);
  const kw = document.getElementById('kw').value.trim();
  if (kw) add('searchkeywords', kw);
  for (const k in vars) vars[k] = vars[k].join(',');
  const enc = encodeURIComponent;
  return 'https://android.jjwxc.net/search/getSearchForKeyWords?offset=' + ((offset|0)) + '&limit=' + PAGE_SIZE
    + '&bq=' + enc(vars.bq || '')
    + '&removetags=' + enc(vars.removebq || '')
    + '&notlikecollectionTypes=' + enc(vars.notlikecollectiontypes || '')
    + '&fw=' + enc(vars.fw || '')
    + '&yc=' + enc(vars.yc || '')
    + '&xx=' + enc(vars.xx || '')
    + '&sd=' + enc(vars.sd || '')
    + '&lx=' + enc(vars.lx || '')
    + '&mainview=' + enc(vars.mainview || '')
    + '&fbsj=' + enc(vars.fbsj || '')
    + '&novelbefavoritedcount=' + enc(vars.novelbefavoritedcount || '')
    + '&isfinish=' + enc(vars.isfinish || '')
    + '&collectionTypes=' + enc(vars.collectiontypes || '')
    + '&searchkeyWords=' + enc(vars.searchkeywords || '')
    + '&sortType=' + enc(vars.sorttype || '');
}


const STEP_MAP = { '2': '完结', '1': '连载', '0': '暂停' };
function esc(s){ return String(s == null ? '' : s)
//.replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); 
}

// 标签随机色：基于标签名做稳定哈希，保证同名标签颜色一致、不会每次渲染都变
function tagColor(name){
  let h = 0;
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) & 0xffffffff;
  const hue = Math.abs(h) % 360;
  return { bg: `hsl(${hue}, 70%, 90%)`, fg: `hsl(${hue}, 65%, 32%)` };
}

function bookHTML(b, page){
  const cover2 = 'https://i9-static.jjwxc.net/novelimage.php?novelid=' + b.novelid;
  const raw = String(b.cover || '').replace(/https?/, 'https').replace(/_\d+_\d+/, '');
  const src = raw || cover2;
  const cover = `<img src="${esc(src)}" alt="封面" loading="lazy" referrerpolicy="no-referrer" onerror="if(this.src!=='${cover2}')this.src='${cover2}'">`;
  const step = STEP_MAP[String(b.novelstep)] || '未知';
  const tags = String(b.tags || '').split(/\s+/).filter(Boolean).map(t => {
    const c = tagColor(t);
    return `<span style="background:${c.bg};color:${c.fg}">${esc(t)}</span>`;
  }).join('');
  const id = esc(b.novelid || '');
  return `<article class="book" data-novelid="${id}" data-page="${page || 1}">
    <div class="book-cover">${cover}</div>
    <div class="book-main">
      <div class="book-title" data-novelid="${id}">${esc(b.novelname)}</div>
      <div class="book-meta">
        <span class="bk-author" data-author="${esc(b.authorid)}">${esc(b.authorname)}</span> ·
        <span class="st st-${esc(b.novelstep)}">${step}</span> ·
        <span class="bk-size">${esc(b.novelSizeformat)}</span>
      </div>
      <div class="book-class" data-class="${esc(b.novelClass)}">${esc(b.novelClass)}</div>
      <div class="book-tags">${tags}</div>
      <div class="book-intro">${esc(b.novelintroshort)}</div>
    </div>
  </article>`;
}

