// ---------- 渲染书单 / 翻页（按页分块：每页一个 .page-block，窗口连续，页码按块判定） ----------
let totalCount = 0, totalPages = 0, loading = false;
let minPage = 0, maxPage = 0;                 // 已加载的「连续页窗口」[minPage, maxPage]
let reachStart = false, reachEnd = false;     // 已确证没有上一页 / 下一页
let adjustingScroll = false;                  // 程序化定位期间暂停翻页（时间兜底解锁，定时器被节流也不会永久锁死）
let lockedUntil = 0;                          // 程序化滚动锁的到期时间戳（硬兜底，见 lockScroll）
let jumpSeq = 0;                              // 跳转令牌：新跳转会让旧请求的迟到结果失效
const pageCache = new Map();                  // page -> items[]，避免重复请求同一页
const listEl = document.getElementById('list');

// 每页渲染为一个 section.page-block：定位「第 N 页」和判定当前页都靠它，不再依赖单本书卡
function pageBlockHTML(items, page){
  return `<section class="page-block" data-page="${page}">` +
    items.map(b => bookHTML(b, page)).join('') +
    `</section>`;
}

// ---------- 顶部 / 底部「哨兵」：用 IntersectionObserver 判定是否滚到了边缘 ----------
// 为什么不用 scrollY / scrollHeight / innerHeight 算？这些量在 WebView、iframe、
// 内部滚动容器里经常不准；而 scroll 事件也可能被节流甚至漏发（停止滚动后不再补发）。
// 哨兵元素进入视野就触发加载，不依赖上述任何一项，是最稳的一层。
const SEN_MARGIN = 500;                 // 提前 500px 进入触发区
let sentinelIO = null;

// 确保列表头尾各有一个哨兵（jumpTo / loadFirstPage 会整体替换 innerHTML，需要重建）
function ensureSentinels(){
  let top = document.getElementById('senTop');
  if (!top){ top = document.createElement('div'); top.id = 'senTop'; top.className = 'sen'; }
  let bot = document.getElementById('senBot');
  if (!bot){ bot = document.createElement('div'); bot.id = 'senBot'; bot.className = 'sen'; }
  if (listEl.firstChild !== top) listEl.insertBefore(top, listEl.firstChild);
  if (listEl.lastChild !== bot) listEl.appendChild(bot);
  observeSentinels();
}

function observeSentinels(){
  if (typeof IntersectionObserver !== 'function') return;
  if (!sentinelIO){
    sentinelIO = new IntersectionObserver(entries => {
      for (const en of entries){
        if (!en.isIntersecting) continue;
        if (en.target.id === 'senBot') tryLoadNext('io-bottom');
        else tryLoadPrev('io-top');
      }
    }, { root: null, rootMargin: SEN_MARGIN + 'px 0px ' + SEN_MARGIN + 'px 0px', threshold: 0 });
  }
  sentinelIO.disconnect();
  const t = document.getElementById('senTop'), b = document.getElementById('senBot');
  if (t) sentinelIO.observe(t);
  if (b) sentinelIO.observe(b);
}

// 哨兵现在是否仍处在触发区（用 getBoundingClientRect，和滚动容器无关）
function nearEdge(which){
  const el = document.getElementById(which === 'bot' ? 'senBot' : 'senTop');
  if (!el) return false;
  if (!el.getClientRects().length) return false;
  const r = el.getBoundingClientRect();
  const vh = window.innerHeight || document.documentElement.clientHeight || 0;
  if (!vh) return false;
  return which === 'bot' ? (r.top <= vh + SEN_MARGIN) : (r.bottom >= -SEN_MARGIN);
}

// 统一的两个方向入口：所有触发源（scroll / IO / 轮询 / scrollend）都走这里
function tryLoadNext(from){
  if (loading || adjustingScroll || !searched) return;
  if (reachEnd) return;
  if (!listEl.querySelector('.page-block')) return;
  dbg('next←' + from);
  appendPage(maxPage + 1);
}
function tryLoadPrev(from){
  if (loading || adjustingScroll || !searched) return;
  if (minPage <= 1){ if (minPage === 1) reachStart = true; return; }
  if (reachStart) return;
  if (!listEl.querySelector('.page-block')) return;
  dbg('prev←' + from);
  prependPage(minPage - 1);
}

// 轻量调试记录（网址加 ?debug=1 时会显示在右下角面板里）
let dbgLog = [];
function dbg(s){
  dbgLog.push(String(s));
  if (dbgLog.length > 6) dbgLog.shift();
}


// 安全地显示 / 隐藏某个节点：节点不存在时静默跳过，绝不抛错
function setDisplay(id, on, val){
  const el = document.getElementById(id);
  if (!el) return null;
  el.style.display = on ? (val || 'block') : 'none';
  return el;
}

// 一次性把「书单区」切到可见状态（节点缺失也不会抛错）
function showListArea(){
  setDisplay('list', true, 'block');
