function ensureNode(id, cls, text, place){
  let el = document.getElementById(id);
  if (el) return el;
  el = document.createElement('div');
  el.id = id;
  if (cls) el.className = cls;
  if (text) el.textContent = text;
  const host = (listEl && listEl.parentNode) || document.body;
  if (place === 'before' && listEl && listEl.parentNode) host.insertBefore(el, listEl);
  else if (listEl && listEl.parentNode) host.insertBefore(el, listEl.nextSibling);
  else host.appendChild(el);
  console.warn('[jjwxc] 页面缺少 #' + id + '，已在 #list 外侧自动补上');
  return el;
}

function setLoadingNext(on){                                   // 底部 / 下一页加载
  ensureNode('loading', 'loading', '加载中…', 'after').style.display = on ? 'flex' : 'none';
}
function setLoadingPrev(on){                                   // 顶部 / 上一页加载
  ensureNode('loadPrev', 'loading', '加载上一页…', 'before').style.display = on ? 'flex' : 'none';
}

// 非破坏性顶部提示：加载失败时只提示，不清空已加载的书单（避免一次失败就让整个列表消失）
function showBanner(msg){
  let b = document.getElementById('errBanner');
  if (!b){ b = document.createElement('div'); b.id = 'errBanner'; b.className = 'err-banner';
           const app = document.querySelector('.app'); (app || document.body).prepend(b); }
  b.textContent = msg; b.style.display = 'block';
  clearTimeout(b._t); b._t = setTimeout(() => { b.style.display = 'none'; }, 4000);
