// 顶部「共 N 本」信息（居中）
function updateResultInfo(){
  const el = document.getElementById('resultInfo');
  if (!el) return;
  el.textContent = totalCount ? `共 ${totalCount} 本` : '';
  el.style.display = totalCount ? 'flex' : 'none';
}

// 仅更新当前页码指示（右下角 + 输入框），不改 totalPages（未知时显示 ?）
function setCurrentPage(page){
  currentPage = page;
  document.getElementById('navCur').textContent = page;
  document.getElementById('navTot').textContent = totalPages || '?';
  document.getElementById('totalPages').textContent = totalPages || '?';
  const pi = document.getElementById('pageInput');
  if (document.activeElement !== pi) pi.value = page;
}

// 根据滚动位置判断当前正在看的是第几页：取视口上部一条参考线，落在哪个 .page-block 就是第几页
// 关键点：参考线落在所有块之外时，兜底取「最后一块」而不是 minPage —— 避免页码在 1 和当前页之间乱跳
function updateCurrentPageFromScroll(){
  const blocks = listEl.querySelectorAll('.page-block');
  if (!blocks.length) return;
  const y = window.scrollY || window.pageYOffset || 0;
  const ref = y + Math.min(window.innerHeight * 0.35, 220);
  let page = null;
  for (const b of blocks){
    const rect = b.getBoundingClientRect();
    const top = rect.top + y, bottom = rect.bottom + y;
    if (ref >= top && ref < bottom){ page = parseInt(b.dataset.page, 10); break; }
    if (ref < top){ page = parseInt(b.dataset.page, 10); break; }   // 参考线落在该块上方的空隙：归下一块
  }
  if (page == null) page = parseInt(blocks[blocks.length - 1].dataset.page, 10);
  if (page && page !== currentPage) setCurrentPage(page);
}

// 统一的数据请求入口：优先用宿主提供的 ajaxAwait(url)（返回 JSON 字符串）
// 若当前环境没有该函数（例如直接用浏览器打开调试），退回原生 fetch，避免整页无数据
function requestText(url){
  if (typeof ajaxAwait === 'function') return Promise.resolve(ajaxAwait(url));
  return fetch(url).then(r => { if (!r.ok) throw new Error('HTTP ' + r.status); return r.text(); });
}

// 真实请求某一页（offset 驱动），并更新总数 / 总页数 / 抽屉请求地址
function fetchPage(page){
  const offset = (page - 1) * PAGE_SIZE;
  const url = buildSearchUrl(offset);
  const reqEl = document.getElementById('reqUrl');
  if (reqEl){ reqEl.textContent = url; reqEl.href = url; }

  let req;
  try { req = requestText(url); }
  catch (e) { return Promise.reject(e); }

  // 超时兜底：请求一直不返回时也要把 loading 放开，否则整套翻页会永久卡死
  let timer;
  const timeout = new Promise((_, rej) => { timer = setTimeout(() => rej(new Error('请求超时')), 15000); });
  return Promise.race([req, timeout])
    .then(res => {
      const data = typeof res === 'string' ? JSON.parse(res) : res;
      const items = Array.isArray(data.items) ? data.items : [];
      // 空结果不覆盖已有总数/总页数：接口对越界 offset 会返回 total=0、total_page=0，
      // 若让它覆盖，顶部「共 N 本」和总页数会被一次性冲掉
      if (items.length){
        if (data.total != null && data.total > 0) totalCount = data.total;
        else if (data.count != null) totalCount = data.count;
        if (data.total_page != null && data.total_page > 0) totalPages = data.total_page;
        else if (totalCount) totalPages = Math.ceil(totalCount / PAGE_SIZE);
      }
      updateResultInfo();
      return items;
    })
    .finally(() => clearTimeout(timer));
}

// 初次搜索：加载第 1 页并铺满首屏
function loadFirstPage(){
  loading = true; searched = true; setLoadingNext(true);
  jumpSeq++;                       // 让仍在飞行中的旧跳转结果失效
  let okRender = false;
  fetchPage(1)
    .then(items => {
      items = items || [];
      if (!items.length){
        listEl.innerHTML = '<div class="list-empty">没有符合条件的作品～</div>';
        showListArea();
        minPage = maxPage = 0; reachStart = reachEnd = true;   // 确证空结果
        return;
      }
      pageCache.set(1, items);
      listEl.innerHTML = pageBlockHTML(items, 1);
      ensureSentinels();                       // 重建头尾哨兵（innerHTML 被整体替换后会丢失）
      showListArea();
      minPage = maxPage = 1;
      reachStart = true; reachEnd = false;
      setCurrentPage(1);
      lockScroll();
      window.scrollTo(0, 0);
      unlockScroll(260);                      // 解锁：锁定期内若有滚动，会补跑一次
      dbg('first-page');
      updateCurrentPageFromScroll();
      okRender = true;
    })
    .catch(err => { showBanner('加载失败：' + err.message + '（可能需登录签名或存在跨域限制）'); })
    .finally(() => {
      setLoadingNext(false); loading = false;
      if (okRender) ensureFill();        // 状态复位后再补充，否则会被 ensureFill 的 loading 守卫挡掉
    });
}

// 方向边界标记：置位后 6 秒自动解除，允许重试
// 接口对越界/异常 offset 也可能返回空，若一次空结果就永久锁死，表现就是「跳转后滚动再也不加载」
let endTimer = 0, startTimer = 0;
function markEnd(){
  reachEnd = true;
  clearTimeout(endTimer);
  endTimer = setTimeout(() => { reachEnd = false; }, 6000);
}
function markStart(){
  reachStart = true;
  clearTimeout(startTimer);
  startTimer = setTimeout(() => { reachStart = false; }, 6000);
}

// 下一页：以 .page-block 追加在列表最下方（插到尾部哨兵之前），不滚动、不打断阅读
function appendPage(page){
  if (loading || page <= maxPage || reachEnd) return Promise.resolve(false);
  const cached = pageCache.get(page);
  const run = (cached && cached.length)
    ? Promise.resolve(cached)
    : fetchPage(page).then(items => { if (items && items.length) pageCache.set(page, items); return items; });
  loading = true; setLoadingNext(true);
  let added = false;
  return run.then(items => {
    items = items || [];
    if (!items.length){                // 空页：不写缓存，只做「暂时到底」，6 秒后可重试
      pageCache.delete(page);
      markEnd();
      dbg('next-empty:' + page);
      return false;
    }
    const html = pageBlockHTML(items, page);
    const bot = document.getElementById('senBot');
    if (bot && bot.parentNode === listEl) bot.insertAdjacentHTML('beforebegin', html);
    else listEl.insertAdjacentHTML('beforeend', html);
    maxPage = Math.max(maxPage, page);
    clearTimeout(endTimer); reachEnd = false;
    dbg('next+:' + page + '(' + items.length + ')');
    if (!adjustingScroll) updateCurrentPageFromScroll();
    added = true;
    return true;
  }).catch(err => { showBanner('下一页加载失败：' + err.message); markEnd(); return false; })
    .finally(() => {
      setLoadingNext(false); loading = false;
      if (added) ensureFill();       // 短页（如末页只有几条）继续向下铺满
    });
}

// 上一页：以 .page-block 插入列表最上方（插到头部哨兵之后），插入后修正滚动位置，视口内容不跳动
function prependPage(page){
  if (loading || page >= minPage || page < 1 || reachStart) return Promise.resolve(false);
  const cached = pageCache.get(page);
  const run = (cached && cached.length)
    ? Promise.resolve(cached)
    : fetchPage(page).then(items => { if (items && items.length) pageCache.set(page, items); return items; });
  loading = true; setLoadingPrev(true);
  return run.then(items => {
    items = items || [];
    if (!items.length){ pageCache.delete(page); markStart(); dbg('prev-empty:' + page); return false; }
    // 视口锚定：记录插入前第一块的位置，插入后用位置差修正滚动，不依赖 scrollHeight
    const firstBlock = listEl.querySelector('.page-block');
    const y0 = window.scrollY || window.pageYOffset || 0;
    const before = firstBlock ? firstBlock.getBoundingClientRect().top : 0;
    const tpl = document.createElement('template');
    tpl.innerHTML = pageBlockHTML(items, page);
    const topSen = document.getElementById('senTop');
    const ref = (topSen && topSen.parentNode === listEl) ? topSen.nextSibling : listEl.firstChild;
    listEl.insertBefore(tpl.content, ref);
    minPage = minPage ? Math.min(minPage, page) : page;
    if (firstBlock){
      const delta = firstBlock.getBoundingClientRect().top - before;
      if (delta) { lockScroll(); window.scrollTo(0, Math.max(0, y0 + delta)); unlockScroll(260); }
    }
    clearTimeout(startTimer); reachStart = false;
    if (page <= 1) markStart();
    dbg('prev+:' + page + '(' + items.length + ')');
    return true;
  }).catch(err => { showBanner('上一页加载失败：' + err.message); markStart(); return false; })
    .finally(() => { setLoadingPrev(false); loading = false; });
}

// 向下补充：最后一块的底部还没离开「视口 + 缓冲」时，继续加载下一页（铺满首屏 / 触底续接）
// 用 getBoundingClientRect 判定，不用 scrollHeight（WebView/iframe 里经常不准）
function ensureFill(){
  if (loading || reachEnd) return;
  const blocks = listEl.querySelectorAll('.page-block');
  if (!blocks.length || blocks.length > 60) return;   // 上限保护：页面高度异常时不无限串行请求
  const last = blocks[blocks.length - 1];
  const vh = window.innerHeight || document.documentElement.clientHeight || 0;
  if (!vh) return;
  if (last.getBoundingClientRect().bottom <= vh + 600) appendPage(maxPage + 1);
}


function jumpTo(page){
  page = parseInt(page, 10);
  if (isNaN(page) || page < 1) return;

  const block = listEl.querySelector('.page-block[data-page="' + page + '"]');
  if (block){
    scrollToBlock(page);
    reachEnd = false;                 // 已加载页附近仍可能补充下一页
    if (page <= 1) reachStart = true;
    setCurrentPage(page);
    dbg('jump-cached:' + page);
    return;
  }

  const seq = ++jumpSeq;
  const want = [page - 1, page, page + 1].filter(p => p >= 1);
  const oldHTML = listEl.innerHTML, oldMin = minPage, oldMax = maxPage;
  const oldRS = reachStart, oldRE = reachEnd;
  let okRender = false;

  loading = true; searched = true; setLoadingNext(true);
  Promise.all(want.map(p =>
    pageCache.has(p) ? Promise.resolve(pageCache.get(p))
                     : fetchPage(p).then(items => {
                         if (items && items.length) pageCache.set(p, items);   // 空页不写缓存，避免之后滚动直接读到空数组
                         return items || [];
                       })
  ))
    .then(results => {
      if (seq !== jumpSeq) return;                       // 已被更新的跳转取代，丢弃本次结果
      let html = '', got = 0, mn = Infinity, mx = -Infinity;
      want.forEach((p, i) => {
        const items = results[i] || [];
        if (!items.length) return;
        html += pageBlockHTML(items, p);
        got += items.length;
        mn = Math.min(mn, p); mx = Math.max(mx, p);
      });
      if (!got){                                        // 目标页无数据：保留原列表，仅提示
        listEl.innerHTML = oldHTML;
        ensureSentinels();
        minPage = oldMin; maxPage = oldMax; reachStart = oldRS; reachEnd = oldRE;
        showBanner('第 ' + page + ' 页没有数据');
        dbg('jump-empty:' + page);
        return;
      }
      listEl.innerHTML = html;
      ensureSentinels();                                // 重建头尾哨兵
      showListArea();
      minPage = mn; maxPage = mx;
      reachStart = (mn <= 1);
      reachEnd = false;                 // 跳转后一律允许两侧继续滚动加载（真实末页由空结果判定）
      setCurrentPage(page);
      scrollToBlock(page);
      updateCurrentPageFromScroll();
      dbg('jump:' + page + ' [' + mn + '-' + mx + ']');
      okRender = true;
    })
    .catch(err => {                                     // 失败：回滚到跳转前的列表
      if (seq !== jumpSeq) return;
      listEl.innerHTML = oldHTML;
      ensureSentinels();
      minPage = oldMin; maxPage = oldMax; reachStart = oldRS; reachEnd = oldRE;
      showBanner('跳转失败：' + err.message);
    })
    .finally(() => {
      if (seq !== jumpSeq) return;                      // 已被更新的跳转接管，不要动 loading 状态
      setLoadingNext(false); loading = false;
      if (okRender) ensureFill();                       // 复位后再补充，避免被 loading 守卫挡掉
    });
}


