// ---------- Base64 状态编码 / 还原（公共前缀 + 仅余下部分编码） ----------
function getCurrentToken(){
  const full = buildSearchUrl();
  const prefix = 'https://android.jjwxc.net/search/getSearchForKeyWords?offset=0&limit=20&bq=';
  const rem = full.indexOf(prefix) === 0 ? full.slice(prefix.length) : full;
  return btoa(rem);
}
function setTagRaw(id, state){
  tagState[id] = state;
  const el = taggrid.querySelector(`[data-id="${id}"]`);
  if (el){ el.classList.remove('inc','exc'); if (state === 1) el.classList.add('inc'); if (state === 2) el.classList.add('exc'); }
}
function restoreState(token){
  let rem;
  try { rem = atob(token); } catch(e){ alert('保存信息已损坏，无法还原'); return false; }
  const p = new URLSearchParams('bq=' + rem);
  resetStateValues();
  (p.get('bq') || '').split(',').forEach(id => { if (id) setTagRaw(id, 1); });
  (p.get('removetags') || '').split(',').forEach(id => { if (id) setTagRaw(id, 2); });
  incMethod = p.get('collectionTypes') === 'ands' ? 'ands' : 'ors';
  excMethod = p.get('notlikecollectionTypes') === 'ands' ? 'ands' : 'ors';
  document.getElementById('kw').value = p.get('searchkeyWords') || '';
  DATA.groups.forEach(g => {
    const urlKey = g.options[0].name === 'sorttype' ? 'sortType' : g.options[0].name.replace(/\d+/g, '');
    const raw = p.get(urlKey);
    if (raw === null) return;
    const set = new Set();
    raw.split(',').forEach(val => { const op = g.options.find(x => String(x.value) === val); if (op) set.add(optKey(op)); });
    if (set.size === 0) set.add(optKey(g.options[FIRST]));
    groupSel[g.label] = set;
  });
  refreshUI();
  updateReqUrl();
  return true;
}

