let lastScrollAt = 0;
let scrollDuringLock = false;         

function lockScroll(){ adjustingScroll = true; lockedUntil = Date.now() + 800; }


function unlockScroll(delay){
  setTimeout(() => {
    if (!adjustingScroll) return;
    adjustingScroll = false; lockedUntil = 0;
    scrollDuringLock = false;
    recheckScroll();
  }, delay);
}

function scrollToBlock(page){
  const b = listEl.querySelector('.page-block[data-page="' + page + '"]');
  if (!b){ window.scrollTo(0, 0); return; }
  const y = window.scrollY || window.pageYOffset || 0;
  const top = b.getBoundingClientRect().top + y;
  lockScroll();
  window.scrollTo(0, Math.max(0, top - 52));
  unlockScroll(260);
}

function onScrollFrame(){
  if (!searched) return;
  try { updateCurrentPageFromScroll(); } catch (e) { }
  if (loading) return;
  if (nearEdge('bot')) tryLoadNext('scroll');
  else if (nearEdge('top')) tryLoadPrev('scroll');
}


function recheckScroll(){
  if (loading || adjustingScroll || !searched) return;
  onScrollFrame();
}

function handleScroll(){
  if (adjustingScroll){
    if (Date.now() < lockedUntil){ scrollDuringLock = true; return; }
    adjustingScroll = false;
  }
  const now = Date.now();
  if (now - lastScrollAt < 50) return;
  lastScrollAt = now;
  onScrollFrame();
}
window.addEventListener('scroll', handleScroll, { passive: true });
document.addEventListener('scroll', handleScroll, { passive: true, capture: true });   
['scrollend', 'touchend', 'touchcancel', 'mouseup'].forEach(ev =>
  window.addEventListener(ev, () => { setTimeout(recheckScroll, 60); }, { passive: true }));

setInterval(() => {
  if (document.visibilityState !== 'visible') return;
  recheckScroll();
}, 1200);

