@js:
(function(){
function esc(s){s=String(s==null?'':s);return s.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');}
function q(n){var m=String(baseUrl).match(new RegExp('[?&]'+n+'=([^&]*)'));try{return m?decodeURIComponent(m[1]):'';}catch(e){return m?m[1]:'';}}
var pid=(String(baseUrl).match(/huaban\.com\/pins\/(\d+)/)||[])[1]||'';
var kset={};var keys=[];
(q('k')||'').split('~').forEach(function(x){if(x&&!kset[x]){kset[x]=1;keys.push(x);}});
if(!keys.length) return '<p style="padding:3em;text-align:center;color:#999">链接数据缺失，请回到列表重新进入</p>';
var bid=q('b')||'';
var h='<style>body{margin:0;padding:8px;background:#faf8f5;font-family:sans-serif}'
 +'h1{font-size:18px;text-align:center;line-height:1.6;margin:14px 4px 2px;font-weight:600}'
 +'.by{text-align:center;color:#999;font-size:13px;margin:2px 0 10px}'
 +'.say{color:#555;font-size:14px;text-align:center;margin:0 16px 12px;line-height:1.7}'
 +'img{display:block;max-width:100%;width:100%;min-height:120px;margin:12px auto 0;border-radius:6px;background:#efe9e1}'
 +'#tip{color:#999;font-size:13px;text-align:center;margin:14px 0}'
 +'.lnk{text-align:center;margin:22px 0;font-size:14px}'
 +'.lnk a{color:#e07911;text-decoration:none}</style>';
h+='<h1>'+esc(q('t'))+'</h1><p class="by">By '+esc(q('u'))+'</p>';
if(q('s')) h+='<p class="say">'+esc(q('s'))+'</p>';
h+='<p class="by" id="cnt">正在统计图片…</p>';
h+='<div id="imgs">';
var fu=q('f');
if(fu) h+='<img src="'+esc(fu.replace(/\?/,'_fw240?'))+'" data-su="'+esc(fu)+'">';
else h+='<img src="https://hbimg.huabanimg.com/'+keys[0]+'_fw240">';
h+='</div>';
if(bid&&pid){
  h+='<scr'+'ipt>(function(){'
   +'var CFG='+JSON.stringify({bid:bid,pid:pid})+';'
   +'var kset={},n=1,ok=0,err=0;'
   +'var tip=document.getElementById("cnt"),box=document.getElementById("imgs"),busy=false,done=false;'
   +'function stat(){tip.textContent="共"+n+" 成"+ok+" 败"+err+(done?"（完）":"");}'
   +'function fin(){ok++;stat();}'
   +'function addImg(su){'
   +'var im=document.createElement("img");im.setAttribute("data-su",su);'
   +'im.src=su.replace(/([^\\/]+)(\\?)/,"$1_fw240$2");'
   +'im.onload=function(){fin();};im.onerror=function(){'
   +'setTimeout(function(){var u=im.src;im.removeAttribute("src");im.src=u;},1200*(im.getAttribute("data-r")||0)+1000);'
   +'var r=im.getAttribute("data-r");if(r==="2"){im.style.border="2px solid #e74c3c";err++;stat();}else{im.setAttribute("data-r",r?String(+r+1):"1");}'
   +'};'
   +'box.appendChild(im);}'
   +'box.addEventListener("click",function(ev){var im=ev.target;'
   +'if(im.tagName==="IMG"&&im.getAttribute("data-su")&&!im.getAttribute("data-hd")){'
   +'im.setAttribute("data-hd","1");im.src=im.getAttribute("data-su");}});'
   +'var m0=box.firstElementChild;'
   +'if(m0&&m0.getAttribute("data-su")){m0.onload=fin;m0.onerror=function(){var r=m0.getAttribute("data-r")||"0";if(r==="2"){err++;stat();}else{m0.setAttribute("data-r",String(+r+1));setTimeout(function(){var u=m0.src;m0.removeAttribute("src");m0.src=u;},1200*+r+1000);}};}'
   +'var last=CFG.pid;'
   +'function more(){if(busy||done)return;busy=true;'
   +'fetch("https://api.huaban.com/v3/boards/"+CFG.bid+"/pins?limit=100&max="+last,{credentials:"include"})'
   +'.then(function(r){return r.json();}).then(function(d){var ps=d.pins||[];'
   +'if(!ps.length){done=true;stat();return;}'
   +'for(var i=0;i<ps.length;i++){var f=ps[i]&&ps[i].file;if(!f||!f.url)continue;var k=String(f.key);if(kset[k])continue;kset[k]=1;n++;'
   +'addImg(String(f.url));}'
   +'last=String(ps[ps.length-1].pin_id);stat();busy=false;'
   +'if(document.body.scrollHeight-window.innerHeight-window.scrollY<2000)more();})'
   +'.catch(function(){busy=false;tip.textContent="加载失败，稍后自动重试";setTimeout(more,3000);});}'
   +'stat();'
   +'window.addEventListener("scroll",function(){if(document.body.scrollHeight-window.innerHeight-window.scrollY<2000)more();},{passive:true});'
   +'var bar=document.createElement("div");'
   +'bar.style.cssText="position:fixed;right:0;top:12%;bottom:12%;width:32px;z-index:99";'
   +'var th=document.createElement("div");'
   +'th.style.cssText="position:absolute;right:6px;width:12px;height:40px;border-radius:6px;background:rgba(224,121,17,.8)";'
   +'bar.appendChild(th);document.body.appendChild(bar);'
   +'function sync(){var d=document.body.scrollHeight-window.innerHeight;if(d<=0)return;var bh=bar.offsetHeight;'
   +'th.style.height=Math.max(36,Math.min(bh*0.3,bh*(window.innerHeight/document.body.scrollHeight)))+"px";'
   +'th.style.top=((window.scrollY/d)*(bh-th.offsetHeight))+"px";}'
   +'window.addEventListener("scroll",sync,{passive:true});window.addEventListener("resize",sync);sync();'
   +'function jump(y){var d=document.body.scrollHeight-window.innerHeight;window.scrollTo(0,Math.max(0,Math.min(d,y*d)));}'
   +'function barY(e){var r=bar.getBoundingClientRect();return (e.touches[0].clientY-r.top)/r.height;}'
   +'var drag=false;'
   +'bar.addEventListener("touchstart",function(e){drag=true;jump(barY(e));sync();e.preventDefault();},{passive:false});'
   +'bar.addEventListener("touchmove",function(e){if(!drag)return;jump(barY(e));sync();e.preventDefault();},{passive:false});'
   +'bar.addEventListener("touchend",function(){drag=false;});'
   +'more();'
   +'})()'
   +'</scr'+'ipt>';
}
h+='<p class="lnk"><a href="https://huaban.com/pins/'+pid+'">在花瓣网查看 · 收藏 · 关注</a></p>';
return h;
})()

